/**
 * Returns true if the token at the given index is the name of a class constant declaration.
 *
 * The name of a constant is always directly followed by `=` and is either
 * directly preceded by `const` or by the tokens of the constant's type declaration.
 */
private function isConstantDeclarationName(Tokens $tokens, int $index): bool
{
    $nextIndex = $tokens->getNextMeaningfulToken($index);

    if (null === $nextIndex || !$tokens[$nextIndex]->equals('=')) {
        return false;
    }

    $prevIndex = $tokens->getPrevMeaningfulToken($index);

    while (null !== $prevIndex && $tokens[$prevIndex]->isGivenKind($this->getTypeSeparationKindsForConstant())) {
        $prevIndex = $tokens->getPrevMeaningfulToken($prevIndex);
    }

    return null !== $prevIndex && $tokens[$prevIndex]->isGivenKind(T_CONST);
}

/**
 * Returns true if the token at the given index is part of the type declaration of a typed constant.
 *
 * Only needed for tokens directly following `const`, as all other type tokens pass
 * the neighbour checks. Tokens like `;` or `,` following the token indicate it is
 * not a type (e.g. the target of a `use const` import), so they are excluded.
 */
private function isConstantTypeHint(Tokens $tokens, int $index): bool
{
    $prevIndex = $tokens->getPrevMeaningfulToken($index);

    if (null === $prevIndex || !$tokens[$prevIndex]->isGivenKind(T_CONST)) {
        return false;
    }

    $nextIndex = $tokens->getNextMeaningfulToken($index);

    if (null === $nextIndex) {
        return false;
    }

    return $tokens[$nextIndex]->isGivenKind([T_STRING])
        || $tokens[$nextIndex]->equalsAny(['|', '&', '(', '?']);
}

/**
 * @return list<int>
 */
private function getTypeSeparationKindsForConstant(): array
{
    return [
        T_STRING,
        T_NS_SEPARATOR,
        CT::T_TYPE_ALTERNATION,
        CT::T_TYPE_INTERSECTION,
        CT::T_NULLABLE_TYPE,
        CT::T_DISJUNCTIVE_NORMAL_FORM_TYPE_PARENTHESIS_OPEN,
        CT::T_DISJUNCTIVE_NORMAL_FORM_TYPE_PARENTHESIS_CLOSE,
